const express = require('express');
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const { createClient } = require('redis');

const redisClient = createClient();
redisClient.connect();

const app = express();
app.use(session({
  store: new RedisStore({ client: redisClient }),
  secret: 'super-session-secret',
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, maxAge: 86400000 } // 1 day
}));

function requireRole(allowedRole) {
  return (req, res, next) => {
    // Assume req.user populated by AuthN middleware
    if (!req.user) return res.status(401).json({ error: 'Unauthenticated' });

    if (req.user.role !== allowedRole) {
      return res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
    }
    next();
  };
}

app.delete('/api/v1/users/:id', requireRole('ADMIN'), (req, res) => {
  res.status(200).json({ message: 'User deleted' });
});

const jwt = require('jsonwebtoken');
const SECRET_KEY = 'super-secret-key';

// Sign JWT token with 15m expiration claim
const token = jwt.sign(
  { userId: 42, role: 'admin' },
  SECRET_KEY,
  { expiresIn: '15m' }
);
console.log('JWT Token:', token);

// Verify token signature and expiration
try {
  const decoded = jwt.verify(token, SECRET_KEY);
  console.log('Valid Decoded Payload:', decoded);
} catch (err) {
  console.error('Invalid or Expired JWT:', err.message);
}

// Express CORS configuration middleware
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', 'https://frontend-app.com');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.setHeader('Access-Control-Allow-Credentials', 'true');
  if (req.method === 'OPTIONS') return res.sendStatus(204); // Handle preflight!
  next();
});

